package screening

// Pushup-track content and program engine: the bundle type, its loader and
// validator, plus the pure functions that turn ONE number — the base B, i.e.
// the last max-test result — into a session plan, an outcome and a weekly
// base change.
//
// Two things make this bundle different from the screening bundles next
// door. First, it carries no third-party instrument: the whole scheme is our
// own implementation of the widely known "max test → individual load →
// several sets with an open last one → retest" pattern, and every number the
// user sees is GENERATED by the formulas below from the parameters in
// pushups_ru.yaml. No table is copied from anywhere — see the yaml header.
// Second, the numbers are load, not score, so the code carries a volume
// ceiling the user never sees (an untrained person doing a naive "as many as
// you can" challenge is the documented overload risk).
//
// Everything here is pure: no clock, no persistence, no Telegram. The state
// (base, week index, effort adjustment) lives in internal/state and is
// passed in.

import (
	"fmt"
	"math"
	"path/filepath"
	"strings"
)

// pushupsFile is the file name LoadPushups expects inside its content dir.
const pushupsFile = "pushups_ru.yaml"

// Session outcomes. A short session is still a completed session — the track
// never blocks progress on it, it only counts toward the weekly rule.
const (
	PushupOutcomeOver  = "over"  // every fixed set done and the open set beat its floor by over_margin
	PushupOutcomePlan  = "plan"  // every fixed set done and the open set reached its floor
	PushupOutcomeShort = "short" // a fixed set missed, or the open set below its floor
)

// Week progression kinds (what ProgressWeek did to the base).
const (
	PushupWeekStrong = "strong" // two or more "over" and no "short"
	PushupWeekSteady = "steady" // no "short"
	PushupWeekHold   = "hold"   // exactly one "short" — base unchanged, week NOT repeated
	PushupWeekRepeat = "repeat" // two or more "short" — base lowered, week repeated
)

// Track goals. The goal branches the plateau logic for the whole life of the
// track, so it is asked once, before the first test.
const (
	PushupGoalReps     = "reps"
	PushupGoalStrength = "strength"
)

// Effort answers of the single post-session question.
const (
	PushupEffortHard = "hard"
	PushupEffortOK   = "ok"
	PushupEffortEasy = "easy"
)

// Gate actions — what a "yes" to a gate question does.
const (
	PushupGateStop       = "stop"        // track does not start at all
	PushupGateEasier     = "easier"      // start joint_pain_step_down steps down the ladder
	PushupGateDoctorNote = "doctor_note" // "check with your doctor" + the easiest offered variation
)

// PushupVariation is one rung of the difficulty ladder. Offered marks the
// rungs the user may pick from in v1; the rest exist so a step down (pain,
// three repeated weeks) or a step up is gradual.
type PushupVariation struct {
	ID      string `yaml:"id"`
	Name    string `yaml:"name"`
	Hint    string `yaml:"hint"`
	Offered bool   `yaml:"offered"`
}

// PushupGateQuestion is one yes/no safety question.
type PushupGateQuestion struct {
	ID    string `yaml:"id"`
	Text  string `yaml:"text"`
	OnYes string `yaml:"on_yes"`
}

// PushupEffortParams are the three steps of the post-session self-report and
// the clamp they accumulate inside.
type PushupEffortParams struct {
	Hard float64 `yaml:"hard"`
	OK   float64 `yaml:"ok"`
	Easy float64 `yaml:"easy"`
	Min  float64 `yaml:"min"`
	Max  float64 `yaml:"max"`
}

// PushupProgressionParams are the weekly rule's numbers.
type PushupProgressionParams struct {
	OverMargin       int     `yaml:"over_margin"`
	StrongOverCount  int     `yaml:"strong_over_count"`
	RepeatShortCount int     `yaml:"repeat_short_count"`
	StrongShare      float64 `yaml:"strong_share"`
	StrongMin        int     `yaml:"strong_min"`
	SteadyShare      float64 `yaml:"steady_share"`
	SteadyMin        int     `yaml:"steady_min"`
	DropShare        float64 `yaml:"drop_share"`
	DropMin          int     `yaml:"drop_min"`
	RepeatForkAfter  int     `yaml:"repeat_fork_after"`
}

// PushupParams is the whole generator as data. Editing it changes the whole
// program without touching the logic — that is the point of keeping it in
// the yaml.
type PushupParams struct {
	MinBase      int `yaml:"min_base"`
	TooLowReps   int `yaml:"too_low_reps"`
	TestCap      int `yaml:"test_cap"`
	MaxRepsInput int `yaml:"max_reps_input"`
	SmallBaseMax int `yaml:"small_base_max"`

	DayFactors          []float64     `yaml:"day_factors"`
	WorkShare           float64       `yaml:"work_share"`
	OpenShare           float64       `yaml:"open_share"`
	SmallBaseOpenShare  float64       `yaml:"small_base_open_share"`
	SetCountThresholds  []int         `yaml:"set_count_thresholds"`
	SetCounts           []int         `yaml:"set_counts"`
	SetOffsets          map[int][]int `yaml:"set_offsets"`
	MinSetReps          int           `yaml:"min_set_reps"`
	SmallBaseMinSetReps int           `yaml:"small_base_min_set_reps"`
	OpenGap             int           `yaml:"open_gap"`
	SmallBaseOpenGap    int           `yaml:"small_base_open_gap"`

	RestSeconds      []int `yaml:"rest_seconds"`
	RestFloorSeconds int   `yaml:"rest_floor_seconds"`
	RestCutSeconds   int   `yaml:"rest_cut_seconds"`
	RestCutBase      int   `yaml:"rest_cut_base"`
	RestBonusStep    int   `yaml:"rest_bonus_step"`

	VolumeCapEarly    float64 `yaml:"volume_cap_early"`
	VolumeCap         float64 `yaml:"volume_cap"`
	EarlySessions     int     `yaml:"early_sessions"`
	DeloadFactor      float64 `yaml:"deload_factor"`
	RetestDeloadShare float64 `yaml:"retest_deload_share"`

	EffortAdj   PushupEffortParams      `yaml:"effort_adj"`
	Progression PushupProgressionParams `yaml:"progression"`

	SessionsPerWeek     int `yaml:"sessions_per_week"`
	RetestEverySessions int `yaml:"retest_every_sessions"`
	JointPainStepDown   int `yaml:"joint_pain_step_down"`
	MinHoursBetween     int `yaml:"min_hours_between"`
	AdvisedHoursBetween int `yaml:"advised_hours_between"`
	PauseRetestDays     int `yaml:"pause_retest_days"`
	PauseDeloadDays     int `yaml:"pause_deload_days"`
	SessionTTLHours     int `yaml:"session_ttl_hours"`
	HistoryCap          int `yaml:"history_cap"`
	LevelStep           int `yaml:"level_step"`
	LevelMax            int `yaml:"level_max"`
	SecondsPerRep       int `yaml:"seconds_per_rep"`
}

