// LoadPushups reads the track's single content file from dir and validates
// it. Any structural deviation is an error — the bot must fail fast at
// startup rather than run with a broken generator.
func LoadPushups(dir string) (*PushupContent, error) {
	var c PushupContent
	if err := loadYAML(filepath.Join(dir, pushupsFile), &c); err != nil {
		return nil, err
	}
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return &c, nil
}

// ─────────────────────────────────────────────────────────────────────────
// Program engine — pure functions over the base B.
// ─────────────────────────────────────────────────────────────────────────

// PlanInput is everything the generator needs. Only Base is required; the
// zero value of EffortAdj is read as "no adjustment yet" (1.0).
//
// SessionsDone selects the volume ceiling (the first EarlySessions sessions
// run under the strict one), and Deload marks the reduced week after a
// dropped retest or a long pause.
type PlanInput struct {
	Base         int
	DayIdx       int     // 0..len(day_factors)-1: easy / medium / hard day
	EffortAdj    float64 // accumulated self-report factor, clamped to [min,max]
	Goal         string  // PushupGoal*
	SessionsDone int
	Deload       bool
	RestBonusSec int // the one-off "+30 s to everything" the user may switch on
}

// PushupPlan is one generated session. Targets holds 4..7 numbers and the
// LAST one is the floor of the open set ("F+", do at least this many), which
// is why the slice is variable-length rather than five fields.
type PushupPlan struct {
	Targets []int
	RestSec int
	Work    int // W, the working number the fixed sets are built from
	Cap     int // the volume ceiling that was applied (reps per session)
}

// SetCount is the number of sets, fixed ones plus the open one.
func (p PushupPlan) SetCount() int { return len(p.Targets) }

// Fixed returns the fixed sets — everything but the open one.
func (p PushupPlan) Fixed() []int {
	if len(p.Targets) == 0 {
		return nil
	}
	return p.Targets[:len(p.Targets)-1]
}

// OpenFloor is the minimum of the open last set (0 for an empty plan).
func (p PushupPlan) OpenFloor() int {
	if len(p.Targets) == 0 {
		return 0
	}
	return p.Targets[len(p.Targets)-1]
}

// PlannedTotal is the session's planned volume: every fixed set plus the
// open set's floor. The actual total is at least this.
func (p PushupPlan) PlannedTotal() int {
	total := 0
	for _, n := range p.Targets {
		total += n
	}
	return total
}

// Plan generates the session for a base. It is deterministic and free of
// side effects: same input, same slice of numbers.
//
//	k = day_factors[d] × effort (× deload_factor on a reduced week)
//	W = max(min_set_reps, round(work_share × B × k))
//	F = max(W + open_gap, round(open_share × B × k))
//
// The fixed sets are W plus the offsets of set_offsets[n]; the open set's
// floor is F.
//
// The SHAPE of the session — how many sets it has — comes from the volume
// ceiling (see cappedOffsets) and depends on the base alone; k then scales
// the numbers inside that shape. That order matters: the ceiling is a safety
// limit the user never sees, and a limit that removed whole sets from the
// heavy day only would make the heavy day the lightest one of the week.
func (c *PushupContent) Plan(in PlanInput) PushupPlan {
	p := &c.Params

	base := in.Base
	if base < p.MinBase {
		base = p.MinBase
	}
	day := puClampInt(in.DayIdx, 0, len(p.DayFactors)-1)

	effort := in.EffortAdj
	if effort == 0 {
		effort = 1
	}
	effort = puClampFloat(effort, p.EffortAdj.Min, p.EffortAdj.Max)

	k := p.DayFactors[day] * effort
	if in.Deload {
		k *= p.DeloadFactor
	}

	capReps := c.volumeCap(base, in.SessionsDone)
	targets, work := c.buildSets(base, k, c.cappedOffsets(base, capReps))

	return PushupPlan{
		Targets: targets,
		RestSec: c.RestSeconds(base, day, in.Goal, in.RestBonusSec),
		Work:    work,
		Cap:     capReps,
	}
}

// buildSets renders the numbers of one session at intensity k: the fixed sets
// (the working number W plus each offset, never below the floor) and, last,
// the floor of the open set.
func (c *PushupContent) buildSets(base int, k float64, offsets []int) ([]int, int) {
	p := &c.Params

	minSet, openShare, gap := p.MinSetReps, p.OpenShare, p.OpenGap
	if base <= p.SmallBaseMax {
		minSet, openShare, gap = p.SmallBaseMinSetReps, p.SmallBaseOpenShare, p.SmallBaseOpenGap
	}

	work := puMaxInt(minSet, puRound(p.WorkShare*float64(base)*k))
	open := puMaxInt(work+gap, puRound(openShare*float64(base)*k))

	targets := make([]int, 0, len(offsets)+1)
	for _, off := range offsets {
		targets = append(targets, puMaxInt(minSet, work+off))
	}
	return append(targets, open), work
}

// volumeCap is the ceiling of one session — volume_cap(_early) × B, in reps.
// The early regime (the first early_sessions sessions) is the tighter one:
// that is the ramp-in an untrained person needs, and the documented overload
// risk of this exercise is exactly a big session done by someone detrained.
func (c *PushupContent) volumeCap(base, sessionsDone int) int {
	share := c.Params.VolumeCap
	if sessionsDone < c.Params.EarlySessions {
		share = c.Params.VolumeCapEarly
	}
	return puRound(share * float64(base))
}

// cappedOffsets is the session's shape: the set template the base earns,
// minus the sets the volume ceiling cannot afford. It drops the
// second-to-last FIXED set while the plan is over the ceiling, down to the
// smallest set count — dropping from the tail of the fixed block removes the
// lightest work first and always keeps the open set, the session's progress
// sensor.
//
// The decision is taken on the NEUTRAL session (k = 1) and therefore depends
// on the base and the ceiling alone. This is deliberate. Measuring the day's
// own plan against a ceiling that does not move with it inverts the week: at
// base 25 in the first six sessions, the fixed ceiling used to cut two sets
// off the hard day and none off the easy one, so the week ran 56 / 63 / 52
// reps — the "hard" day the lightest of the three. The self-report had the
// same cliff under it: "легко" raised k, the plan crossed the ceiling, a set
// was dropped and the NEXT session came out lighter, while the text promised
// it would be denser. With the shape fixed per base, k only scales numbers,
// so heavier input always means a heavier session.
//
// The ceiling thus bounds an average-intensity session at volume_cap × B;
// the hard day of a maximal self-report is heavier by its own factor
// (day_factors[last] × effort_adj.max ≈ 1.32 of it), which is the shape of a
// week rather than an escape from the limit.
//
// A plan may still exceed the ceiling once it is down to the minimum set
// count: at that point the load is already the base's own honest minimum and
// cutting further would leave nothing to train.
func (c *PushupContent) cappedOffsets(base, capReps int) []int {
	offsets := c.Params.SetOffsets[c.setCount(base)]
	minOffsets := c.Params.SetCounts[0] - 1 // the open set is not an offset
	for len(offsets) > minOffsets {
		neutral, _ := c.buildSets(base, 1, offsets)
		total := 0
		for _, n := range neutral {
			total += n
		}
		if total <= capReps {
			break
		}
		drop := len(offsets) - 2 // the second-to-last fixed set
		trimmed := make([]int, 0, len(offsets)-1)
		trimmed = append(trimmed, offsets[:drop]...)
		trimmed = append(trimmed, offsets[drop+1:]...)
		offsets = trimmed
	}
	return offsets
}

// setCount picks the number of sets for a base from the thresholds.
func (c *PushupContent) setCount(base int) int {
	p := &c.Params
	n := p.SetCounts[0]
	for i, threshold := range p.SetCountThresholds {
		if base >= threshold && i+1 < len(p.SetCounts) {
			n = p.SetCounts[i+1]
		}
	}
	return n
}

// RestSeconds is the rest between sets for a day. Goal "more reps" with a
// high base shortens it (but never below the floor); the user's one-off
// bonus is added on top. Resting LONGER is never a miss — the track only
// pings, it does not punish.
func (c *PushupContent) RestSeconds(base, dayIdx int, goal string, bonusSec int) int {
	p := &c.Params
	day := puClampInt(dayIdx, 0, len(p.RestSeconds)-1)
	rest := p.RestSeconds[day]
	if goal == PushupGoalReps && base >= p.RestCutBase {
		rest = puMaxInt(p.RestFloorSeconds, rest-p.RestCutSeconds)
	}
	if bonusSec > 0 {
		rest += bonusSec
	}
	return rest
}

// EstimateMinutes is the rough duration of a plan (working time plus rests),
// rounded up — the "≈ N minutes" of the session texts.
func (c *PushupContent) EstimateMinutes(plan PushupPlan) int {
	if plan.SetCount() == 0 {
		return 0
	}
	seconds := plan.PlannedTotal()*c.Params.SecondsPerRep + (plan.SetCount()-1)*plan.RestSec
	return int(math.Ceil(float64(seconds) / 60))
}

// Level is the cosmetic level shown next to the base: 1 + base/level_step,
// capped at level_max. It is derived, never stored.
func (c *PushupContent) Level(base int) int {
	if base < 0 {
		base = 0
	}
	return puClampInt(1+base/c.Params.LevelStep, 1, c.Params.LevelMax)
}

// ClassifySession maps a plan and what actually happened onto one of the
// three outcomes. actual is index-aligned with targets; missing entries
// count as zero, so an abandoned session classifies as PushupOutcomeShort
// instead of panicking.
//
//	every fixed set done AND open ≥ floor + over_margin → over
//	every fixed set done AND open ≥ floor               → plan
//	otherwise                                           → short
func (c *PushupContent) ClassifySession(targets, actual []int) string {
	if len(targets) == 0 {
		return PushupOutcomeShort
	}
	openIdx := len(targets) - 1
	for i := 0; i < openIdx; i++ {
		if answerAt(actual, i) < targets[i] {
			return PushupOutcomeShort
		}
	}
	got, floor := answerAt(actual, openIdx), targets[openIdx]
	switch {
	case got >= floor+c.Params.Progression.OverMargin:
		return PushupOutcomeOver
	case got >= floor:
		return PushupOutcomePlan
	default:
		return PushupOutcomeShort
	}
}

// PushupWeek is the verdict on a finished week: what happens to the base and
// whether the week is repeated. A repeat is ALWAYS announced out loud — a
// silent rollback reads as a bug.
type PushupWeek struct {
	Kind        string // PushupWeek*
	NewBase     int
	Delta       int // NewBase - base, may be negative
	Repeat      bool
	StreakGrows bool
}

// ProgressWeek applies the weekly rule to the week's outcomes. Progression
// follows the RESULT, not the calendar — the base is the only state, so
// there are no coverage holes between "columns" by construction.
//
//	≥ strong_over_count "over" and no "short" → +max(strong_min, strong_share × B)
//	no "short"                                → +max(steady_min, steady_share × B)
//	exactly one "short"                       → base unchanged, week NOT repeated
//	≥ repeat_short_count "short"              → −max(drop_min, drop_share × B), repeat
func (c *PushupContent) ProgressWeek(base int, outcomes []string) PushupWeek {
	pr := &c.Params.Progression
	if base < c.Params.MinBase {
		base = c.Params.MinBase
	}

	over, short := 0, 0
	for _, o := range outcomes {
		switch o {
		case PushupOutcomeOver:
			over++
		case PushupOutcomeShort:
			short++
		}
	}

	switch {
	case short >= pr.RepeatShortCount:
		drop := puMaxInt(pr.DropMin, puRound(pr.DropShare*float64(base)))
		newBase := puMaxInt(c.Params.MinBase, base-drop)
		return PushupWeek{
			Kind:    PushupWeekRepeat,
			NewBase: newBase,
			Delta:   newBase - base,
			Repeat:  true,
		}
	case short > 0:
		// One bad session is not a reason to redo the week.
		return PushupWeek{Kind: PushupWeekHold, NewBase: base, StreakGrows: true}
	case over >= pr.StrongOverCount:
		gain := puMaxInt(pr.StrongMin, puRound(pr.StrongShare*float64(base)))
		return PushupWeek{
			Kind: PushupWeekStrong, NewBase: base + gain, Delta: gain, StreakGrows: true,
		}
	default:
		gain := puMaxInt(pr.SteadyMin, puRound(pr.SteadyShare*float64(base)))
		return PushupWeek{
			Kind: PushupWeekSteady, NewBase: base + gain, Delta: gain, StreakGrows: true,
		}
	}
}

// PushupTestVerdict is what a max test means for the program.
type PushupTestVerdict struct {
	Base     int  // the new base
	Capped   bool // hit the test ceiling → offer a harder variation and retest
	TooLow   bool // at or below too_low_reps → the variation is too hard
	StepDown bool // TooLow and there is a lighter rung to step onto
}

// ClassifyTest turns a raw test result into the new base. Reps above the
// ceiling are capped (and the user is offered a harder variation instead of
// a longer set); a result at or below too_low_reps means the variation is
// too hard — step down the ladder and retest at once, or, when already on
// the easiest rung, just floor the base.
func (c *PushupContent) ClassifyTest(reps int, canStepDown bool) PushupTestVerdict {
	p := &c.Params
	v := PushupTestVerdict{}
	if reps >= p.TestCap {
		reps = p.TestCap
		v.Capped = true
	}
	if reps <= p.TooLowReps {
		v.TooLow = true
		v.StepDown = canStepDown
	}
	v.Base = puMaxInt(p.MinBase, reps)
	return v
}

// RetestNeedsDeload reports whether a retest dropped far enough below the
// old base to run one reduced week (instead of "rolling back to week N",
// which this track has no notion of).
func (c *PushupContent) RetestNeedsDeload(oldBase, newBase int) bool {
	if oldBase <= 0 {
		return false
	}
	return float64(newBase) < c.Params.RetestDeloadShare*float64(oldBase)
}

// NextEffortAdj accumulates the post-session self-report onto the current
// adjustment and clamps it. An unknown answer leaves the value untouched.
func (c *PushupContent) NextEffortAdj(current float64, answer string) float64 {
	e := &c.Params.EffortAdj
	if current == 0 {
		current = 1
	}
	step := 0.0
	switch answer {
	case PushupEffortHard:
		step = e.Hard
	case PushupEffortOK:
		step = e.OK
	case PushupEffortEasy:
		step = e.Easy
	}
	return puClampFloat(current+step, e.Min, e.Max)
}

// ─────────────────────────────────────────────────────────────────────────
// Ladder helpers (content-driven, pure).
// ─────────────────────────────────────────────────────────────────────────

// VariationIndex is the rung's position on the ladder, or -1 when unknown.
func (c *PushupContent) VariationIndex(id string) int {
	for i, v := range c.Variations.Ladder {
		if v.ID == id {
			return i
		}
	}
	return -1
}

// Variation returns the rung by id, or nil.
func (c *PushupContent) Variation(id string) *PushupVariation {
	if i := c.VariationIndex(id); i >= 0 {
		return &c.Variations.Ladder[i]
	}
	return nil
}

// ShiftVariation moves steps rungs along the ladder (negative = easier) and
// clamps at both ends. An unknown id returns the default rung.
func (c *PushupContent) ShiftVariation(id string, steps int) string {
	i := c.VariationIndex(id)
	if i < 0 {
		return c.Variations.DefaultID
	}
	return c.Variations.Ladder[puClampInt(i+steps, 0, len(c.Variations.Ladder)-1)].ID
}

// OfferedVariations are the rungs the user may pick from.
func (c *PushupContent) OfferedVariations() []PushupVariation {
	out := make([]PushupVariation, 0, len(c.Variations.Ladder))
	for _, v := range c.Variations.Ladder {
		if v.Offered {
			out = append(out, v)
		}
	}
	return out
}

// ─────────────────────────────────────────────────────────────────────────
// Validation
// ─────────────────────────────────────────────────────────────────────────

// canonicalPushupGate pins the three gate questions: their ids, their order
// and what a "yes" does. A file with a different gate is not the content
// this code was written for.
var canonicalPushupGate = []PushupGateQuestion{
	{ID: "health", OnYes: PushupGateStop},
	{ID: "joint_pain", OnYes: PushupGateEasier},
	{ID: "pregnancy", OnYes: PushupGateDoctorNote},
}

// Validate checks the bundle against the canonical shape and pins the
// generator's invariants. An error means "refuse to start".
func (c *PushupContent) Validate() error {
	if err := c.validatePushupTexts(); err != nil {
		return fmt.Errorf("screening: pushups: %w", err)
	}
	if err := c.validatePushupLadder(); err != nil {
		return fmt.Errorf("screening: pushups: ladder: %w", err)
	}
	if err := c.validatePushupParams(); err != nil {
		return fmt.Errorf("screening: pushups: params: %w", err)
	}
	if err := c.validatePushupBranding(); err != nil {
		return fmt.Errorf("screening: pushups: %w", err)
	}
	return nil
}

func (c *PushupContent) validatePushupTexts() error {
	for name, s := range c.userTexts() {
		if strings.TrimSpace(s) == "" {
			return fmt.Errorf("empty %s", name)
		}
	}
	if len(c.Test.RepRules) < 4 {
		return fmt.Errorf("want at least 4 rep rules, got %d", len(c.Test.RepRules))
	}
	if len(c.Test.StopRules) < 2 {
		return fmt.Errorf("want at least 2 stop rules, got %d", len(c.Test.StopRules))
	}
	if len(c.RedCard.Signs) < 4 {
		return fmt.Errorf("want at least 4 red-flag signs, got %d", len(c.RedCard.Signs))
	}
	if len(c.Gate.Questions) != len(canonicalPushupGate) {
		return fmt.Errorf("want %d gate questions, got %d", len(canonicalPushupGate), len(c.Gate.Questions))
	}
	for i, want := range canonicalPushupGate {
		got := c.Gate.Questions[i]
		if got.ID != want.ID || got.OnYes != want.OnYes {
			return fmt.Errorf("gate question %d is %s/%s, want %s/%s",
				i+1, got.ID, got.OnYes, want.ID, want.OnYes)
		}
	}
	return nil
}

func (c *PushupContent) validatePushupLadder() error {
	ladder := c.Variations.Ladder
	if len(ladder) < 4 {
		return fmt.Errorf("want at least 4 rungs, got %d", len(ladder))
	}
	seen := map[string]bool{}
	offered := 0
	for i, v := range ladder {
		if strings.TrimSpace(v.ID) == "" || strings.TrimSpace(v.Name) == "" {
			return fmt.Errorf("rung %d has an empty id or name", i+1)
		}
		if seen[v.ID] {
			return fmt.Errorf("duplicate rung %q", v.ID)
		}
		seen[v.ID] = true
		if v.Offered {
			offered++
		}
	}
	if offered < 2 {
		return fmt.Errorf("want at least 2 offered rungs, got %d", offered)
	}
	if c.VariationIndex(c.Variations.DefaultID) < 0 {
		return fmt.Errorf("default_id %q is not on the ladder", c.Variations.DefaultID)
	}
	return nil
}

func (c *PushupContent) validatePushupParams() error {
	p := &c.Params

	if p.MinBase < 1 {
		return fmt.Errorf("min_base must be >= 1, got %d", p.MinBase)
	}
	if p.TooLowReps < 0 || p.TooLowReps >= p.TestCap {
		return fmt.Errorf("too_low_reps %d is not below test_cap %d", p.TooLowReps, p.TestCap)
	}
	if p.TestCap < 20 || p.TestCap > p.MaxRepsInput {
		return fmt.Errorf("test_cap %d out of range (20..%d)", p.TestCap, p.MaxRepsInput)
	}
	if p.SmallBaseMax < p.MinBase {
		return fmt.Errorf("small_base_max %d below min_base %d", p.SmallBaseMax, p.MinBase)
	}

	if len(p.DayFactors) != p.SessionsPerWeek {
		return fmt.Errorf("want %d day factors, got %d", p.SessionsPerWeek, len(p.DayFactors))
	}
	for i, f := range p.DayFactors {
		if f <= 0 {
			return fmt.Errorf("day factor %d is %v", i, f)
		}
		if i > 0 && f <= p.DayFactors[i-1] {
			return fmt.Errorf("day factors must ascend: %v", p.DayFactors)
		}
	}
	if len(p.RestSeconds) != p.SessionsPerWeek {
		return fmt.Errorf("want %d rest values, got %d", p.SessionsPerWeek, len(p.RestSeconds))
	}
	for i, r := range p.RestSeconds {
		if r < p.RestFloorSeconds {
			return fmt.Errorf("rest %d (%ds) below the floor %ds", i, r, p.RestFloorSeconds)
		}
	}
	if p.RestFloorSeconds <= 0 || p.RestCutSeconds < 0 || p.RestBonusStep <= 0 {
		return fmt.Errorf("rest parameters must be positive")
	}

	if p.WorkShare <= 0 || p.WorkShare >= 1 {
		return fmt.Errorf("work_share %v out of range (0,1)", p.WorkShare)
	}
	if p.OpenShare <= p.WorkShare || p.OpenShare >= 1 {
		return fmt.Errorf("open_share %v must be above work_share and below 1", p.OpenShare)
	}
	if p.SmallBaseOpenShare < p.OpenShare {
		return fmt.Errorf("small_base_open_share %v below open_share %v", p.SmallBaseOpenShare, p.OpenShare)
	}
	if p.MinSetReps < 1 || p.SmallBaseMinSetReps < 1 || p.SmallBaseMinSetReps > p.MinSetReps {
		return fmt.Errorf("set-rep floors are inconsistent: %d / %d", p.MinSetReps, p.SmallBaseMinSetReps)
	}
	if p.OpenGap < 1 || p.SmallBaseOpenGap < 1 || p.SmallBaseOpenGap > p.OpenGap {
		return fmt.Errorf("open gaps are inconsistent: %d / %d", p.OpenGap, p.SmallBaseOpenGap)
	}

	if len(p.SetCounts) < 2 || len(p.SetCountThresholds) != len(p.SetCounts)-1 {
		return fmt.Errorf("want %d thresholds for %d set counts, got %d",
			len(p.SetCounts)-1, len(p.SetCounts), len(p.SetCountThresholds))
	}
	for i, n := range p.SetCounts {
		if n < 3 {
			return fmt.Errorf("set count %d is %d", i, n)
		}
		if i > 0 && n <= p.SetCounts[i-1] {
			return fmt.Errorf("set counts must ascend: %v", p.SetCounts)
		}
		offsets, ok := p.SetOffsets[n]
		if !ok {
			return fmt.Errorf("no set_offsets for %d sets", n)
		}
		if len(offsets) != n-1 {
			return fmt.Errorf("set_offsets[%d] has %d entries, want %d", n, len(offsets), n-1)
		}
		for j, off := range offsets {
			if off < -2 || off > 2 {
				return fmt.Errorf("set_offsets[%d][%d] = %d is out of range [-2,2]", n, j, off)
			}
		}
	}
	for i, t := range p.SetCountThresholds {
		if t <= 0 {
			return fmt.Errorf("threshold %d is %d", i, t)
		}
		if i > 0 && t <= p.SetCountThresholds[i-1] {
			return fmt.Errorf("thresholds must ascend: %v", p.SetCountThresholds)
		}
	}
	if len(p.SetOffsets) != len(p.SetCounts) {
		return fmt.Errorf("set_offsets has %d entries, want %d", len(p.SetOffsets), len(p.SetCounts))
	}

	if p.VolumeCapEarly <= 0 || p.VolumeCap <= p.VolumeCapEarly {
		return fmt.Errorf("volume ceilings are inconsistent: %v / %v", p.VolumeCapEarly, p.VolumeCap)
	}
	if p.EarlySessions <= 0 {
		return fmt.Errorf("early_sessions must be positive, got %d", p.EarlySessions)
	}
	if p.DeloadFactor <= 0 || p.DeloadFactor >= 1 {
		return fmt.Errorf("deload_factor %v out of range (0,1)", p.DeloadFactor)
	}
	if p.RetestDeloadShare <= 0 || p.RetestDeloadShare >= 1 {
		return fmt.Errorf("retest_deload_share %v out of range (0,1)", p.RetestDeloadShare)
	}

	e := &p.EffortAdj
	if e.Hard >= 0 || e.Easy <= 0 || e.OK != 0 {
		return fmt.Errorf("effort steps must be −/0/+, got %v/%v/%v", e.Hard, e.OK, e.Easy)
	}
	if e.Min >= 1 || e.Max <= 1 {
		return fmt.Errorf("effort clamp %v..%v must contain 1", e.Min, e.Max)
	}

	pr := &p.Progression
	if pr.OverMargin < 1 || pr.StrongOverCount < 1 || pr.RepeatShortCount < 2 {
		return fmt.Errorf("progression counters are inconsistent: %+v", *pr)
	}
	if pr.StrongShare <= pr.SteadyShare || pr.SteadyShare <= 0 {
		return fmt.Errorf("progression shares are inconsistent: %v / %v", pr.StrongShare, pr.SteadyShare)
	}
	if pr.StrongMin < pr.SteadyMin || pr.SteadyMin < 1 || pr.DropMin < 1 || pr.DropShare <= 0 {
		return fmt.Errorf("progression minimums are inconsistent: %+v", *pr)
	}
	if pr.RepeatForkAfter < 2 {
		return fmt.Errorf("repeat_fork_after must be >= 2, got %d", pr.RepeatForkAfter)
	}

	if p.RetestEverySessions < p.SessionsPerWeek {
		return fmt.Errorf("retest_every_sessions %d below a week", p.RetestEverySessions)
	}
	if p.JointPainStepDown < 1 {
		return fmt.Errorf("joint_pain_step_down must be >= 1, got %d", p.JointPainStepDown)
	}
	if p.MinHoursBetween < 1 || p.AdvisedHoursBetween < p.MinHoursBetween {
		return fmt.Errorf("recovery hours are inconsistent: %d / %d", p.MinHoursBetween, p.AdvisedHoursBetween)
	}
	if p.PauseRetestDays < 1 || p.PauseDeloadDays <= p.PauseRetestDays {
		return fmt.Errorf("pause thresholds are inconsistent: %d / %d", p.PauseRetestDays, p.PauseDeloadDays)
	}
	if p.SessionTTLHours < 1 || p.HistoryCap < 1 || p.LevelStep < 1 || p.LevelMax < 1 || p.SecondsPerRep < 1 {
		return fmt.Errorf("storage/level parameters must be positive")
	}
	return nil
}

// pushupSourceBranding is the branding of the commercial program this track
// deliberately does NOT copy. Assembled from bytes so this file itself never
// spells it out — same trick as forbiddenBranding in content.go.
var pushupSourceBranding = []string{
	string([]byte{'h', 'u', 'n', 'd', 'r', 'e', 'd', 'p', 'u', 's', 'h', 'u', 'p', 's'}),
	string([]byte{'s', 'p', 'e', 'i', 'r', 's'}),
	string([]byte{'o', 'n', 'e', ' ', 'h', 'u', 'n', 'd', 'r', 'e', 'd', ' ', 'p', 'u', 's', 'h'}),
}

// validatePushupBranding refuses content mentioning either the copyrighted
// third-party interview instrument (the repository-wide guard) or the
// commercial pushup program whose tables this track must never reproduce.
func (c *PushupContent) validatePushupBranding() error {
	for where, s := range c.userTexts() {
		low := strings.ToLower(s)
		if strings.Contains(low, forbiddenBranding) {
			return fmt.Errorf("%s contains forbidden instrument branding", where)
		}
		for _, needle := range pushupSourceBranding {
			if strings.Contains(low, needle) {
				return fmt.Errorf("%s names the commercial source program", where)
			}
		}
	}
	return nil
}

