// ─────────────────────────────────────────────────────────────────────────
// Small numeric helpers (package-private, pushup-scoped names).
// ─────────────────────────────────────────────────────────────────────────

func puRound(f float64) int { return int(math.Round(f)) }

func puMaxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func puClampInt(v, lo, hi int) int {
	if hi < lo {
		return lo
	}
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

func puClampFloat(v, lo, hi float64) float64 {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}
